(()=>{'use strict';const form=document.querySelector('#quote-form');if(!form)return;form.hidden=false;
const tr=window.wavingTranslate||(s=>s),fr=document.documentElement.lang==='fr-CA';
const content=document.querySelector('#step-content'),prev=document.querySelector('#previous'),next=document.querySelector('#next'),error=document.querySelector('#form-error');
const needs=['Buy Flags','Custom Flags','Buy Flagpole','Flagpole Installation','Flag Rental','Flagpole Rental','Flagpole Repair','Flag Replacement','Commercial Flag Service','Multi-Location Program','Other'];
let step=0,busy=false,files=[],started=Date.now(),data={};const params=new URLSearchParams(location.search);if(needs.includes(params.get('need')))data.need=params.get('need');if(params.get('city'))data.city=params.get('city');if(params.get('topic'))data.topic=params.get('topic').slice(0,160);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function event(name,extra={}){window.dispatchEvent(new CustomEvent('waving:analytics',{detail:{event:name,step:step+1,...extra}}));}event('quote_start');
function field(name,label,type='text',required=false,options=[],hint=''){let control;if(type==='select')control=`<select id="q-${name}" name="${name}" ${required?'required':''}><option value="">${tr('Choose an option')}</option>${options.map(o=>`<option value="${e(o)}" ${data[name]===o?'selected':''}>${e(tr(o))}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea id="q-${name}" name="${name}" maxlength="4000" ${required?'required':''}>${e(data[name])}</textarea>`;else control=`<input id="q-${name}" name="${name}" type="${type}" value="${e(data[name])}" ${required?'required':''} ${type==='number'?'min="1" max="100000" step="1"':''} ${type==='text'?'maxlength="200"':''} ${name==='email'?'autocomplete="email"':name==='name'?'autocomplete="name"':name==='phone'?'autocomplete="tel"':name==='company'?'autocomplete="organization"':name==='postal'?'autocomplete="postal-code"':name==='city'?'autocomplete="address-level2"':''}>`;return `<label class="field" for="q-${name}"><span>${tr(label)}${required?' *':tr(' (optional)')}</span>${control}${hint?`<small>${tr(hint)}</small>`:''}</label>`}
function save(){content.querySelectorAll('input,select,textarea').forEach(el=>{if(el.type==='file')return;if(el.type==='radio'){if(el.checked)data[el.name]=el.value}else if(el.type==='checkbox')data[el.name]=el.checked;else data[el.name]=el.value})}
function showError(message,focus){error.textContent=tr(message);error.hidden=false;if(focus){focus.setAttribute('aria-invalid','true');focus.focus();}event('quote_validation_error')}
function valid(){save();error.hidden=true;content.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));for(const el of content.querySelectorAll('input,select,textarea')){if(el.type==='file')continue;if((el.required&&typeof el.value==='string'&&!el.value.trim())||!el.checkValidity()){const label=el.closest('label')?.querySelector('span')?.textContent?.replace(' *','')||'this field';showError(el.validity.valueMissing?`Please complete ${label.toLowerCase()}.`:`Please check ${label.toLowerCase()}.`,el);return false}}return true}
function render(){
 error.hidden=true;prev.hidden=true;next.textContent=tr('REQUEST MY QUOTE');
 content.innerHTML='<h2>What do you need?</h2><p class="notice">Share what you know. Fields marked * are required.</p>'+
 (data.topic?'<p class="notice">'+tr('Project focus:')+' '+e(tr(data.topic))+'</p>':'')+
 field('need','Request','select',true,needs)+'<div class="form-grid">'+field('name','Name','text',true)+field('email','Email','email',true)+field('phone','Phone','tel')+field('city','City or community','text',true)+'</div>'+
 field('notes','Project details','textarea',false,[],'Include deadlines, access requirements or additional services. Avoid sensitive personal information.')+
 '<details class="quote-attachments"><summary>Choose files (optional)</summary><label class="field"><span>Choose files (optional)</span><input type="file" id="files" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.svg,.ai,.eps"><small>Up to 5 files. Maximum 10 MB per file and 20 MB total. JPG, PNG, WebP, PDF, SVG, AI or EPS. Do not include confidential documents.</small></label><ul id="file-list" class="file-list"></ul></details>'+
 '<label class="consent"><input type="checkbox" name="consent" required><span>I agree to be contacted about this request and have read the <a href="/privacy/" target="_blank" rel="noopener">privacy information</a>. This is not marketing consent. *</span></label>';
 window.wavingLocalize?.(content);drawFiles();document.querySelector('#files').addEventListener('change',addFiles);event('quote_form_view');
}
function drawFiles(){const list=document.querySelector('#file-list');list.replaceChildren();files.forEach((f,i)=>{const li=document.createElement('li');li.textContent=`${f.name} (${(f.size/1048576).toFixed(1)} ${fr?'Mo':'MB'}) `;const b=document.createElement('button');b.type='button';b.textContent=tr('REMOVE');b.setAttribute('aria-label',(fr?'Retirer ':'Remove ')+f.name);b.addEventListener('click',()=>{files.splice(i,1);drawFiles()});li.append(b);list.append(li)})}
function addFiles(ev){const selected=[...ev.target.files];let merged=[...files];for(const f of selected){if(!/\.(jpe?g|png|webp|pdf|svg|ai|eps)$/i.test(f.name)){showError('That file type is not supported. Choose an image, PDF or supported artwork file.');ev.target.value='';return}if(f.size>10*1048576){showError('Each file must be 10 MB or smaller.');ev.target.value='';return}if(!merged.some(x=>x.name===f.name&&x.size===f.size))merged.push(f)}if(merged.length>5||merged.reduce((a,f)=>a+f.size,0)>20*1048576){showError('Choose up to five files with a combined size of 20 MB or less.');ev.target.value='';return}files=merged;error.hidden=true;drawFiles();ev.target.value=''}
next.addEventListener('click',async()=>{if(busy||!valid())return;await submit()});form.addEventListener('submit',ev=>{ev.preventDefault();next.click()});
async function submit(){const cfg=window.WAVING_CONFIG||{};if(!cfg.quoteEndpoint){showError('Your request could not be sent right now. Your entries are still here. Please call (833) 696-9996 to discuss your quote.');event('quote_submit_unavailable');return}if(form.elements._gotcha.value||Date.now()-started<3000){showError('Please review your request and try again.');return}busy=true;next.disabled=true;prev.disabled=true;next.textContent=tr('SENDING…');form.setAttribute('aria-busy','true');const payload=new FormData();for(const [k,v]of Object.entries(data))if(v!==''&&v!==false)payload.append(k,String(v));files.forEach(f=>payload.append('attachment',f,f.name));payload.append('_subject','Waving quote request — '+data.need);payload.append('_gotcha','');payload.append('language',document.documentElement.lang);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const r=await fetch(cfg.quoteEndpoint,{method:'POST',body:payload,headers:{Accept:'application/json'},signal:controller.signal});let result={};try{result=await r.json()}catch{throw new Error('Invalid response')}if(!r.ok||result.ok!==true||result.errors)throw new Error('Not accepted');form.hidden=true;const success=document.querySelector('#quote-success');success.hidden=false;success.setAttribute('tabindex','-1');success.focus();event('quote_submit_accepted')}catch(err){showError('We could not confirm that your request was accepted. Your entries are still here. Please try again later or call (833) 696-9996.');event('quote_submit_error')}finally{clearTimeout(timer);busy=false;next.disabled=false;prev.disabled=false;next.textContent=tr('REQUEST MY QUOTE');form.removeAttribute('aria-busy')}}
render();})();
